const input = $json || {};
const classId = typeof input.class_id === 'string' ? input.class_id.trim() : '';
const uuidPattern = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const weeks = Number(input.weeks || 2);
const limit = Number(input.limit || 12);
const isValid = uuidPattern.test(classId);
return {
  json: {
    class_id: isValid ? classId : null,
    weeks,
    limit,
    is_valid: isValid,
    status: isValid ? 'validated' : 'invalid_class_id',
    reason: isValid ? null : 'invalid_class_id',
    validation_error: isValid ? null : 'class_id is empty or malformed',
  }
};

const rows = $input.all().map((item) => item.json || {});
const triggerInput = $('Execute Workflow Trigger').first().json || {};
const firstRow = rows[0] || {};
if (firstRow.is_valid === false || firstRow.status === 'invalid_class_id') {
  return {
    json: {
      class_id: firstRow.class_id || null,
      weeks: Number(firstRow.weeks || triggerInput.weeks || 2),
      limit: Number(firstRow.limit || triggerInput.limit || 12),
      status: 'invalid_class_id',
      reason: firstRow.reason || 'invalid_class_id',
      batch_size: 0,
      week_start: null,
      source_window: {
        weeks: Number(firstRow.weeks || triggerInput.weeks || 2),
        n: 0,
        class_id: firstRow.class_id || null,
      },
      contributing_students_count: 0,
      rows: [],
      validation_error: firstRow.validation_error || 'class_id is empty or not a valid uuid',
    }
  };
}
const normalizedRows = rows.map((row) => ({
  week_start: row.week_start || null,
  created_at: row.created_at || null,
  comment_text: typeof row.comment_text === 'string' ? row.comment_text.trim() : '',
  avg_mood: row.avg_mood ?? null,
  avg_pace: row.avg_pace ?? null,
  avg_fairness: row.avg_fairness ?? null,
})).filter((row) => row.comment_text.length > 0);
const sourceWindow = firstRow.source_window ?? { weeks: Number(triggerInput.weeks || 2), n: 0, class_id: triggerInput.class_id || null };
const weekStart = firstRow.week_start ?? null;
const contributingStudentsCount = Number(firstRow.contributing_students_count ?? sourceWindow.n ?? 0);
return {
  json: {
    class_id: triggerInput.class_id || null,
    weeks: Number(triggerInput.weeks || 2),
    limit: Number(triggerInput.limit || 12),
    status: normalizedRows.length > 0 ? 'ready' : 'no_safe_batch',
    reason: normalizedRows.length > 0 ? null : 'no_safe_batch',
    batch_size: normalizedRows.length,
    week_start: weekStart,
    source_window: sourceWindow,
    contributing_students_count: contributingStudentsCount,
    rows: normalizedRows,
  }
};
